DROP TABLE IF EXISTS `accesos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `accesos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `venta_id` bigint(20) unsigned NOT NULL,
  `boleto_evento_id` bigint(20) unsigned NOT NULL,
  `tipo_boleto` varchar(50) NOT NULL DEFAULT 'B-TIPO',
  `clave_evento` varchar(50) NOT NULL,
  `numero_control` varchar(50) NOT NULL,
  `hash_seguridad` varchar(100) NOT NULL,
  `token_qr` varchar(255) NOT NULL,
  `seccion_pasillo` varchar(100) NOT NULL,
  `fila_palco` varchar(100) NOT NULL,
  `numero_asiento` varchar(50) NOT NULL,
  `estatus` enum('pendiente','validado','revocado') NOT NULL DEFAULT 'pendiente',
  `escaneado_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `accesos_token_qr_unique` (`token_qr`),
  KEY `accesos_venta_id_foreign` (`venta_id`),
  KEY `accesos_boleto_evento_id_foreign` (`boleto_evento_id`),
  CONSTRAINT `accesos_boleto_evento_id_foreign` FOREIGN KEY (`boleto_evento_id`) REFERENCES `boletos_evento` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `accesos_venta_id_foreign` FOREIGN KEY (`venta_id`) REFERENCES `ventas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=169 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
