--
-- Table structure for table `asientos`
--

DROP TABLE IF EXISTS `asientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `asientos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `teatro_id` bigint(20) unsigned NOT NULL,
  `zona_teatro_id` bigint(20) unsigned DEFAULT NULL,
  `fila` varchar(10) NOT NULL,
  `numero` int(11) NOT NULL,
  `codigo` varchar(20) NOT NULL,
  `slot_index` int(11) NOT NULL,
  `tipo` enum('asiento','pasillo') NOT NULL DEFAULT 'asiento',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `asientos_teatro_fila_numero_unique` (`teatro_id`,`fila`,`numero`),
  KEY `asientos_zona_teatro_id_foreign` (`zona_teatro_id`),
  CONSTRAINT `asientos_teatro_id_foreign` FOREIGN KEY (`teatro_id`) REFERENCES `teatros` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `asientos_zona_teatro_id_foreign` FOREIGN KEY (`zona_teatro_id`) REFERENCES `zonas_teatro` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6991 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

