--
-- Table structure for table `asientos_evento`
--

DROP TABLE IF EXISTS `asientos_evento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `asientos_evento` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `evento_id` bigint(20) unsigned NOT NULL,
  `asiento_id` bigint(20) unsigned NOT NULL,
  `estado` enum('disponible','reservado','bloqueado','vendido') NOT NULL DEFAULT 'disponible',
  `reservado_por_usuario_id` bigint(20) unsigned DEFAULT NULL,
  `venta_id` bigint(20) unsigned DEFAULT NULL,
  `reservado_hasta` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
